13	// tryLock acquires an exclusive, non-blocking flock on the data directory.
14	// The kernel releases it automatically on exit or if the process is killed,
15	// so a later instance can take over immediately.
16	func tryLock(file *os.File) error {
17		if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
18			if errors.Is(err, syscall.EWOULDBLOCK) {
19				return errLocked
20			}
21			return err
